      senior: { name: 'Senior debt', why: 'Lenders are paid first, in full, before any shareholder sees a dollar.' },
      venture: { name: 'Venture debt', why: 'Paid after senior debt and before any shareholder.' },
      b: { name: 'Series B preferred', why: 'Takes its $60M back first, or converts to 25% when that is worth more. It converts above a $290M sale.' },
      a: { name: 'Series A preferred', why: 'Takes its $20M after Series B, or converts to 20% when that is worth more. It converts above a $185M sale.' },
